// Writes drizzle/0003_journal_triggers.sql from the table definitions in scripts/lib/journal.js.
// Run it after changing JOURNAL_TABLES, then add a new migration that drops and recreates the
// triggers (an applied migration must never change).
import fs from 'node:fs';
import path from 'node:path';
import { ROOT } from '../lib/db.js';
import { triggerSql } from '../lib/journal.js';

const out = path.join(ROOT, 'drizzle', process.argv[2] ?? '0003_journal_triggers.sql');
const header =
	'-- Change journal for incremental backups (generated by scripts/dev/journal-triggers.mjs).\n' +
	'-- Every write to user data is appended to change_log; see scripts/lib/journal.js.\n';
fs.writeFileSync(out, header + triggerSql().join('\n--> statement-breakpoint\n') + '\n');
console.log(`wrote ${path.relative(ROOT, out)}`);
